const I18N = { pcm: new Map(), ur: new Map(), bn: new Map() };
for (const [en, pcm, ur, bn] of I18N_ROWS) {
  if (pcm) I18N.pcm.set(en, pcm);
  if (ur) I18N.ur.set(en, ur);
  if (bn) I18N.bn.set(en, bn);
}

// i18n('Page {0}/{1}', 3, 10) fills by position; i18n('#{n} on {board}', { n, board }) fills by name.
// Not called t(): the game code has 100+ local variables named t (elapsed time) that would shadow it.
function i18n(en, ...args) {
  const lang = typeof CURRENT_LANG === 'string' ? CURRENT_LANG : 'en';
  const table = I18N[lang];
  let text = (table && table.get(en)) || en;
  if (args.length === 1 && args[0] !== null && typeof args[0] === 'object') {
    const vars = args[0];
    return text.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? String(vars[k]) : m));
  }
  if (args.length) text = text.replace(/\{(\d+)\}/g, (m, i) => (args[i] !== undefined ? String(args[i]) : m));
  return text;
}
